{
  "name": "mcp-vk-ads",
  "version": "1.8.3",
  "description": "MCP server for the VK Ads (VK Реклама) API — manage ad plans, ad groups, banners and pull statistics from AI agents.",
  "mcpName": "io.github.askads/mcp-vk-ads",
  "type": "module",
  "bin": {
    "mcp-vk-ads": "dist/index.js"
  },
  "files": [
    "dist",
    "test",
    "npm-shrinkwrap.json"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "rm -rf dist && tsc",
    "start": "node dist/index.js",
    "dev": "tsx watch src/index.ts",
    "typecheck": "tsc -p tsconfig.check.json",
    "smoke": "node --import tsx src/smoke.ts",
    "test": "npm run test:src && npm run test:dist",
    "test:src": "node --import tsx --test $(find src -name '*.test.ts')",
    "test:dist": "npm run build && node --test test/dist-smoke.test.js",
    "prepare": "npm run build",
    "prepublishOnly": "npm run typecheck && npm test",
    "version": "npm shrinkwrap && git add npm-shrinkwrap.json"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "vk",
    "vk-ads",
    "advertising"
  ],
  "license": "MIT",
  "author": "Aleksandr Kovalko",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/askads/mcp-vk-ads.git"
  },
  "homepage": "https://github.com/askads/mcp-vk-ads#readme",
  "bugs": {
    "url": "https://github.com/askads/mcp-vk-ads/issues"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.29.0",
    "zod": "^3.25.0"
  },
  "devDependencies": {
    "@types/node": "^25.9.3",
    "tsx": "^4.22.4",
    "typescript": "^5.7.0"
  }
}

