{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.askads/mcp-vk-ads",
  "title": "VK Ads MCP",
  "description": "MCP server for VK Ads (VK Реклама) API: manage ad plans, ad groups, banners, and statistics.",
  "websiteUrl": "https://github.com/askads/mcp-vk-ads#readme",
  "repository": {
    "url": "https://github.com/askads/mcp-vk-ads",
    "source": "github"
  },
  "version": "1.8.3",
  "packages": [
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "mcp-vk-ads",
      "version": "1.8.3",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "VK_ADS_TOKEN",
          "description": "Optional ready-made VK Ads OAuth2 access token (Bearer) for CI and unattended installs — full account access, treat it as a secret. Without it the server connects from the chat via start_login/finish_login.",
          "isRequired": false,
          "isSecret": true
        },
        {
          "name": "VK_ADS_LANG",
          "description": "Language for API responses (Accept-Language header), e.g. ru, en.",
          "isRequired": false,
          "default": "ru"
        },
        {
          "name": "VK_ADS_TIMEOUT_MS",
          "description": "Per-request timeout in milliseconds.",
          "isRequired": false,
          "default": "60000"
        },
        {
          "name": "VK_ADS_MAX_RETRIES",
          "description": "Max retries for transient errors (429 rate limit, 5xx on GET, network errors on GET).",
          "isRequired": false,
          "default": "3"
        },
        {
          "name": "VK_ADS_API_BASE",
          "description": "API root without a version segment. Defaults to https://ads.vk.com/api.",
          "isRequired": false,
          "default": "https://ads.vk.com/api"
        }
      ]
    }
  ]
}

