      "src": "https://raw.githubusercontent.com/ClickHouse/loom/main/integrations/claude-code-plugin/assets/icon.png",
      "mimeType": "image/png",
      "sizes": ["1024x1024"]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://{loom_host}/mcp",
      "variables": {
