              "description": "Loom writer token (JWT)",
              "isRequired": true,
              "isSecret": true
            }
          }
        }
      ]
    }
  ],
  "_meta": {
    "io.modelcontextprotocol.registry/publisher-provided": {
      "documentation": "https://clickhouse.github.io/loom/getting-started/connect-a-coding-agent/",
